        {
            _grain = grain;
        }

        public async ValueTask HandleAsync(WorkResponse message, IInboxHandlerContext context, CancellationToken cancellationToken)
        {
            _grain._completedTasks.Add(message);
            await _grain.WriteStateAsync();
        }
    }
}

