        {
            SessionPool = sessionPool,
            SenderId = this.GetGrainId()
        };

        var envelope = builder
            .To(workerId, "ProcessData")
            .WithBody(request)
            .WithCorrelationKey(correlationKey)
            .WithReplyTo(this.GetGrainId())
            .Build();

        _outbox.Send(envelope);
        await WriteStateAsync();
    }

