        get
        {
            var length = 0;
            foreach (var segment in this)
            {
                // Account for segment separators.
                if (length > 0)
                {
                    ++length;
                }

                length += segment.Length;
            }

            return length;
        }
    }

    /// <inheritdoc/>
    public override bool Equals(object? obj)
    {
        if (obj is not CorrelationKey other)
        {
            return false;
        }

        return Equals(other);
    }

    /// <inheritdoc/>
    public override int GetHashCode()
    {
