        /// Advances the enumerator to the next segment.
        /// </summary>
        /// <returns>True if there is a next segment; otherwise, false.</returns>
        public bool MoveNext()
        {
            if (_buffer.Length == 0)
            {
                if (!_enumerator.MoveNext())
                {
                    return false;
                }

                _buffer = _enumerator.Current;
