            Current = GetNextSegment();
            _buffer = _buffer[Current.Length..];

            if (_buffer.Length > 0 && _buffer[0] == SegmentSeparator)
            {
                _buffer = _buffer[1..];
            }

            while (Current.Length == 0)
            {
