        {
            var buffer = _buffer;
            var isEscaped = false;
            var length = 0;
            foreach (var c in buffer)
            {
                ++length;
                if (c == EscapeCharacter)
                {
                    isEscaped = !isEscaped;
                    continue;
                }
                else if (c == SegmentSeparator && !isEscaped)
                {
