            if (context.Envelope.Data.TryGetBody<int>(out var intValue))
            {
                _grain._handledSuccessfully = true;
            }
            else
            {
                // Type mismatch detected - this is expected
                _grain._typeMismatchDetected = true;
            }

            await _grain.WriteStateAsync();
